record.field:
if record.x_appointment_type_id:
    action = {
        "type": "ir.actions.act_window",
        "res_model": "calendar.event",
        "view_mode": "gantt",
        "view_id": env.ref("appointment.calendar_event_view_gantt_booking_resource").id,
        "context": {
            "default_appointment_type_id": record.x_appointment_type_id.id,
            "default_name": record.x_appointment_type_id.name,
            "default_res_model": record._name,
            "default_res_id": record.id,
            "default_duration": record.x_appointment_type_id.appointment_duration,
            "default_x_task_id": record.id,
            "default_partner_ids" : [(6, 0, [record.partner_id.id])] if record.partner_id else [],
        },
    }

action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'message': "Please select a Customer and a Vehicle", 'type': 'warning'}}
if record.partner_id and record.x_vehicle_id:
    order = env['sale.order'].create({
        'partner_id': record.partner_id.id,
        'x_vehicle_id': record.x_vehicle_id.id,
        'x_chassis_number': record.x_chassis_number,
        'x_task_id': record.id,
    })
    record['sale_order_id'] = order.id
    action = {'type': 'ir.actions.act_window', 'res_model': 'sale.order', 'view_mode': 'form', 'res_id': order.id}

action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'message': "Please select a Customer and a Vehicle", 'type': 'warning'}}
if record.partner_id and record.x_vehicle_id:
    invoice = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': record.partner_id.id,
        'x_vehicle_id': record.x_vehicle_id.id,
        'x_chassis_number': record.x_chassis_number,
        'x_task_id': record.id,
    })
    record['x_is_invoiced'] = True
    action = {'type': 'ir.actions.act_window', 'res_model': 'account.move', 'view_mode': 'form', 'res_id': invoice.id}

for task in records:
    env['fleet.vehicle.odometer'].create({
        'value': task.x_odometer,
        'vehicle_id': task.x_vehicle_id.id,
        'driver_id': task.x_vehicle_id.driver_id.id,
    })

if (token := request.params.get('event_token')) and (event_sudo := env['calendar.event'].sudo().search([('access_token', '=', token), ('appointment_type_id', '!=', False)], limit=1)):
    event_sudo.write({'appointment_status': 'booked'})
    env['calendar.attendee'].sudo().search([('event_id', '=', event_sudo.id)]).write({'state': 'accepted'})
    if (partner := request.params.get('partner_id')):
        response = request.redirect("calendar/view/%s?partner_id=%s" % (token, partner))
